import{_ as o,o as e,c as s,ag as a}from"./chunks/framework.DXGyWiRo.js";const m=JSON.parse('{"title":"Cost Optimization Skill","description":"","frontmatter":{},"headers":[],"relativePath":"skills/cost-optimization.md","filePath":"skills/cost-optimization.md"}'),i={name:"skills/cost-optimization.md"};function n(d,t,r,l,c,p){return e(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="cost-optimization-skill" tabindex="-1">Cost Optimization Skill <a class="header-anchor" href="#cost-optimization-skill" aria-label="Permalink to &quot;Cost Optimization Skill&quot;">​</a></h1><p>The Cost Optimization Skill identifies cost-saving opportunities across Azure resources and estimates potential monthly savings.</p><h2 id="capability" tabindex="-1">Capability <a class="header-anchor" href="#capability" aria-label="Permalink to &quot;Capability&quot;">​</a></h2><ul><li>Retrieves cost-related Azure Advisor recommendations</li><li>Estimates aggregate monthly savings across subscriptions</li><li>Provides actionable cost reduction plans</li></ul><h2 id="skill-configuration" tabindex="-1">Skill Configuration <a class="header-anchor" href="#skill-configuration" aria-label="Permalink to &quot;Skill Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td>Skill Name</td><td><code>CostOptimizationSkill</code></td></tr><tr><td>Model</td><td><code>gpt-4o</code></td></tr><tr><td>Temperature</td><td><code>0.0</code></td></tr><tr><td>Timeout</td><td><code>120s</code></td></tr></tbody></table><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>CostOptimizationTools-GetCostRecommendations</code></td><td><code>GetCostRecommendations(subscriptionIds)</code></td><td>Filters Advisor recommendations by category <code>Cost</code>; returns recommendations with savings estimates</td></tr><tr><td><code>CostOptimizationTools-EstimateSavings</code></td><td><code>EstimateSavings(subscriptionIds)</code></td><td>Aggregates all cost recommendation savings amounts; returns total potential monthly savings</td></tr><tr><td><code>AdvisorRecommendationTools-GetRecommendations</code></td><td><code>GetRecommendations(subscriptionIds, &quot;Cost&quot;)</code></td><td>Queries advisorresources for cost recommendations (up to 20)</td></tr><tr><td><code>AdvisorRecommendationTools-GetRecommendationDetails</code></td><td><code>GetRecommendationDetails(recommendationId)</code></td><td>Returns full details for a single Advisor recommendation</td></tr><tr><td><code>SubscriptionTools-ListResourceGroups</code></td><td><code>ListResourceGroups(subscriptionId)</code></td><td>Lists resource groups for scoping</td></tr><tr><td><code>ResourceGraphTools-QueryResources</code></td><td><code>QueryResources(subscriptionIds, resourceType?)</code></td><td>General resource lookup</td></tr></tbody></table><h2 id="how-savings-are-calculated" tabindex="-1">How Savings Are Calculated <a class="header-anchor" href="#how-savings-are-calculated" aria-label="Permalink to &quot;How Savings Are Calculated&quot;">​</a></h2><p>The <code>EstimateSavings</code> tool aggregates savings from Advisor recommendations:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>For each cost recommendation:</span></span>
<span class="line"><span>    if savingsAmount exists:</span></span>
<span class="line"><span>        total += savingsAmount</span></span>
<span class="line"><span>    else if annualSavingsAmount exists:</span></span>
<span class="line"><span>        total += annualSavingsAmount / 12</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The Cost Management Query API is not used. All cost data comes from Azure Advisor recommendations via Azure Resource Graph.</p></div><h2 id="data-sources" tabindex="-1">Data Sources <a class="header-anchor" href="#data-sources" aria-label="Permalink to &quot;Data Sources&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Azure Advisor Recommendations</span></span>
<span class="line"><span>    └─ advisorresources | category == &quot;Cost&quot;</span></span>
<span class="line"><span>    └─ properties.extendedProperties.savingsAmount</span></span>
<span class="line"><span>    └─ properties.extendedProperties.annualSavingsAmount</span></span></code></pre></div><h2 id="example-query" tabindex="-1">Example Query <a class="header-anchor" href="#example-query" aria-label="Permalink to &quot;Example Query&quot;">​</a></h2><blockquote><p>&quot;How can I reduce costs across my subscriptions?&quot;</p></blockquote><p><strong>Tool Calls:</strong></p><ol><li><code>CostOptimizationTools-GetCostRecommendations([&quot;sub-001&quot;, &quot;sub-002&quot;])</code> → cost recommendations</li><li><code>CostOptimizationTools-EstimateSavings([&quot;sub-001&quot;, &quot;sub-002&quot;])</code> → total monthly savings estimate</li><li><code>AdvisorRecommendationTools-GetRecommendations([&quot;sub-001&quot;, &quot;sub-002&quot;], &quot;Cost&quot;)</code> → detailed cost recs</li></ol><p><strong>Output:</strong> Structured markdown with cost recommendations, estimated savings, and prioritized action plan.</p>`,19)])])}const h=o(i,[["render",n]]);export{m as __pageData,h as default};
